<?php
require_once '../includes/verificar_admin.php';
require_once '../config/conexion.php';
require_once '../includes/centro_operaciones.php';
$tipo=is_string($_GET['tipo']??null)&&in_array($_GET['tipo'],['ventas','pedidos'],true)?$_GET['tipo']:'ventas';
$estado=is_string($_GET['estado']??null)&&in_array($_GET['estado'],['Pendiente','Atendida','Descartada','Resuelta','Todas'],true)?$_GET['estado']:'Pendiente';
$pagina=max(1,min(1000,(int)($_GET['pagina']??1)));$error='';$aviso=$_SESSION['operaciones_aviso']??'';unset($_SESSION['operaciones_aviso']);
try{
    preparar_centro_operaciones($conexion);
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        exigir_post();gestionar_accion_dia($conexion,(string)($_POST['clave']??''),(string)($_POST['estado']??''),(string)($_POST['motivo']??''),(int)$_SESSION['id_usuario']);
        $_SESSION['operaciones_aviso']='Estado y motivo guardados en MySQL. Esto no modifica pedidos ni existencias.';header('Location: operaciones.php?'.http_build_query(['tipo'=>$tipo,'estado'=>$estado,'pagina'=>$pagina]).'#acciones');exit;
    }
    evaluar_pronosticos_guardados($conexion);sincronizar_acciones_dia($conexion);
    $comparacion=comparacion_real($conexion,$tipo);$dia=date('Y-m-d');$params=[$dia];$where='dia=?';if($estado!=='Todas'){$where.=' AND estado=?';$params[]=$estado;}
    $q=$conexion->prepare('SELECT COUNT(*) FROM acciones_dia WHERE '.$where);$q->execute($params);$total=(int)$q->fetchColumn();
    $q=$conexion->prepare('SELECT * FROM acciones_dia WHERE '.$where.' ORDER BY prioridad,creada,clave LIMIT 30 OFFSET '.(($pagina-1)*30));$q->execute($params);$acciones=$q->fetchAll(PDO::FETCH_ASSOC);
    $q=$conexion->prepare('SELECT estado,COUNT(*) total FROM acciones_dia WHERE dia=? GROUP BY estado');$q->execute([$dia]);$conteos=array_column($q->fetchAll(PDO::FETCH_ASSOC),'total','estado');
    $q=$conexion->prepare('SELECT h.*,a.titulo FROM acciones_historial h JOIN acciones_dia a ON a.clave=h.accion ORDER BY h.fecha DESC,h.id DESC LIMIT 10');$q->execute();$historial=$q->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){error_log('Centro de operaciones: '.$e->getMessage());$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo actualizar el centro. Revisa MySQL e intenta de nuevo.';}
function valor_operaciones($valor,string $tipo): string {return $valor===null?'—':($tipo==='ventas'?'S/ ':'').number_format((float)$valor,$tipo==='ventas'?2:0);}
?>
