<?php if(!$acciones): ?><div class="ops-empty">No hay acciones con este estado para hoy.</div><?php endif; ?>
<div class="ops-pagination"><span><?= count($acciones) ?> de <?= $total ?> acciones · Página <?= $pagina ?></span><?php if($pagina>1): ?><a href="?<?= e(http_build_query(['tipo'=>$tipo,'estado'=>$estado,'pagina'=>$pagina-1])) ?>#acciones">← Anterior</a><?php endif; ?><?php if($pagina*30<$total): ?><a href="?<?= e(http_build_query(['tipo'=>$tipo,'estado'=>$estado,'pagina'=>$pagina+1])) ?>#acciones">Siguiente →</a><?php endif; ?></div>
